import React from "react";
import { Navigate, useLocation } from "react-router-dom";

// PrivateRoute component for protecting routes with role-based access
const PrivateRoute = ({ element, allowedRoles, ...rest }) => {
  const role = localStorage.getItem("userRole"); // Get the user's role
  const token = localStorage.getItem("authToken"); // Get the authentication token
  const location = useLocation(); // Get the current location to pass to the redirect

  // If there is no token (i.e., the user is not authenticated), redirect to login
  if (!token) {
    return <Navigate to="/login" state={{ from: location }} />;
  }

  // If the role is not allowed to access the route, redirect to home or a default page
  if (allowedRoles && !allowedRoles.includes(role)) {
    return <Navigate to="/" state={{ from: location }} />;
  }

  // If authentication and role check pass, render the element (route component)
  return element;
};

export default PrivateRoute;
